import type { GroundTruthTrust } from '../../types';

/**
 * Shared presentational parts for the ServiceQuality sub-cards (T158 rule 4).
 * Moved VERBATIM from ServiceQualityPanel.tsx during the Measure-shell fold —
 * markup and class strings are byte-identical to the pre-split panel.
 */

export const PERIOD_LABELS: Record<string, string> = {
  am_rush: 'AM peak (06-09)',
  midday: 'Midday (09-15)',
  pm_rush: 'PM peak (15-19)',
  late_night: 'Late night',
  off: 'Off-peak (02-06)',
};

export const PERIOD_ACCENTS: Record<string, string> = {
  am_rush: 'text-accent',
  midday: 'text-bottleneck',
  pm_rush: 'text-optimized',
  late_night: 'text-text-secondary',
  off: 'text-text-secondary',
};

export function StatCard({
  label,
  value,
  sub,
  tone,
}: {
  label: string;
  value: string;
  sub?: string;
  tone?: 'green' | 'amber' | 'neutral';
}) {
  const valueClass =
    tone === 'green'
      ? 'text-optimized'
      : tone === 'amber'
        ? 'text-bottleneck'
        : 'text-text-primary';
  return (
    <div className="card-glow rounded-xl border border-border bg-card p-3.5">
      <div className="text-[10px] font-semibold uppercase tracking-wider text-text-muted">
        {label}
      </div>
      <div className={`mt-1.5 text-2xl font-extrabold tabular-nums leading-none ${valueClass}`}>
        {value}
      </div>
      {sub && <div className="mt-1 text-[10px] leading-snug text-text-muted">{sub}</div>}
    </div>
  );
}

export function TrustBadge({ trust }: { trust: GroundTruthTrust }) {
  const cls =
    trust === 'validated'
      ? 'border-optimized/30 bg-optimized/10 text-optimized'
      : trust === 'biased'
        ? 'border-bottleneck/40 bg-bottleneck/10 text-bottleneck'
        : trust === 'directional'
          ? 'border-accent/30 bg-accent/10 text-accent'
          : 'border-border bg-card-hover text-text-muted';
  const label =
    trust === 'validated'
      ? 'Validated'
      : trust === 'biased'
        ? 'Sensor bias'
        : trust === 'directional'
          ? 'Directional'
          : 'Insufficient n';
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${cls}`}
    >
      {label}
    </span>
  );
}

export function SectionHeader({
  icon,
  title,
  tone,
  freshness,
}: {
  icon: React.ReactNode;
  title: string;
  tone: 'green' | 'amber' | 'blue';
  freshness?: React.ReactNode;
}) {
  const cls =
    tone === 'green'
      ? 'bg-optimized/15 text-optimized'
      : tone === 'amber'
        ? 'bg-bottleneck/15 text-bottleneck'
        : 'bg-accent/15 text-accent';
  const edge =
    tone === 'green' ? 'edge-gradient-green' : tone === 'amber' ? 'edge-gradient-amber' : 'edge-gradient-blue';
  return (
    <div className="relative flex items-center gap-2.5 px-5 pt-5 pb-3">
      <div className={`absolute inset-x-0 top-0 h-0.5 ${edge}`} />
      <span className={`rounded-lg p-1.5 ${cls}`}>{icon}</span>
      <h3 className="text-sm font-bold text-text-primary">{title}</h3>
      {freshness && <span className="ml-auto shrink-0">{freshness}</span>}
    </div>
  );
}

