import { Users, AlertTriangle } from 'lucide-react';
import { fmtNum1, fmtPct } from '../../../lib/format';
import { PERIOD_LABELS, PERIOD_ACCENTS, SectionHeader } from '../shared';
import { EmptyState } from '../../PanelStates';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function CrowdingCard({ sq }: { sq: SqCardProps }) {
  return (
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <div id="sq-crowding">
          <SectionHeader
            icon={<Users className="h-4 w-4" />}
            title="Crowding (APC load)"
            tone="green"
            freshness={sq.crowd.available ? (
              <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                {Object.values(sq.crowd.periods ?? {}).flat().reduce((s, r) => s + (r.n_observations ?? 0), 0).toLocaleString()} obs
              </span>
            ) : undefined}
          />
          </div>
          {sq.crowd.available && Object.values(sq.crowd.periods ?? {}).some((rows) => rows.some((r) => r.mean_pax_calibrated != null)) && (
            <div className="flex items-center gap-2 px-5 pb-2">
              <button
                onClick={() => sq.setShowCalibrated(false)}
                className={`rounded-full px-2.5 py-0.5 text-[10px] font-semibold transition-colors ${
                  !sq.showCalibrated
                    ? 'bg-green-500/15 text-green-400 border border-green-500/30'
                    : 'text-text-muted hover:bg-card-hover border border-transparent'
                }`}
              >
                Raw sensor (%)
              </button>
              <button
                onClick={() => sq.setShowCalibrated(true)}
                className={`rounded-full px-2.5 py-0.5 text-[10px] font-semibold transition-colors ${
                  sq.showCalibrated
                    ? 'bg-green-500/15 text-green-400 border border-green-500/30'
                    : 'text-text-muted hover:bg-card-hover border border-transparent'
                }`}
              >
                Calibrated (pax)
              </button>
              <span className="text-[9px] text-text-muted">
                {sq.showCalibrated ? 'Ground-truth corrected counts' : 'APC bucket-converted percentages'}
              </span>
            </div>
          )}
          {sq.groundTruth && sq.groundTruth.available && sq.groundTruth.floor_share_pct != null && (
            <div className="px-5 pb-2 text-[10px] leading-snug text-text-muted">
              Load % reads in 20%-multiples with a wide floor —{' '}
              <span className="font-semibold text-bottleneck">
                {fmtPct(sq.groundTruth.floor_share_pct)} of ride-along check-ins sat at the 20%
                floor
              </span>
              , so these averages overstate load on quiet routes. See ground-truth calibration
              below.
            </div>
          )}
          {sq.crowd.available ? (
            Object.entries(sq.crowd.periods ?? {}).map(([period, rows]) => {
              const hasCal = rows.some((r) => r.mean_pax_calibrated != null);
              return (
                <div key={period} className="px-5 pb-4">
                  <div
                    className={`pb-1.5 pt-1 text-[11px] font-bold uppercase tracking-wider ${
                      PERIOD_ACCENTS[period] ?? 'text-text-secondary'
                    }`}
                  >
                    {PERIOD_LABELS[period] ?? period}
                  </div>
                  <table className="data-table w-full text-left text-xs">
                    <thead>
                      <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
                        <th className="py-1.5 pr-3 font-semibold">Route</th>
                        <th className="py-1.5 pr-3 font-semibold">Crowded share</th>
                        {sq.showCalibrated && hasCal ? (
                          <th className="py-1.5 pr-3 font-semibold" title="Ground-truth corrected passenger count">
                            Mean pax
                          </th>
                        ) : (
                          <th className="py-1.5 pr-3 font-semibold">Mean load %</th>
                        )}
                        {sq.showCalibrated && hasCal ? (
                          <th className="py-1.5 text-right font-semibold" title="90th percentile calibrated pax">
                            Worst 10% (pax)
                          </th>
                        ) : (
                          <th className="py-1.5 text-right font-semibold">Worst 10%</th>
                        )}
                      </tr>
                    </thead>
                    <tbody>
                      {rows.map((r) => (
                        <tr
                          key={`${period}|${r.route_short_name}`}
                          className="border-b border-border/50 text-text-secondary"
                        >
                          <td className="py-1.5 pr-3 font-bold text-text-primary">
                            Route {r.route_short_name}
                          </td>
                          <td className="py-1.5 pr-3 tabular-nums">
                            {fmtPct(r.crowded_share_pct)}
                          </td>
                          {sq.showCalibrated && hasCal ? (
                            <td className="py-1.5 pr-3 tabular-nums">
                              {r.mean_pax_calibrated != null ? (
                                <span className="font-semibold text-text-primary">
                                  {fmtNum1(r.mean_pax_calibrated)} pax
                                </span>
                              ) : (
                                <span className="text-text-muted">—</span>
                              )}
                            </td>
                          ) : (
                            <td className="py-1.5 pr-3 tabular-nums">{fmtNum1(r.mean_percentage)}%</td>
                          )}
                          <td
                            className={`py-1.5 text-right tabular-nums font-semibold ${
                              (sq.showCalibrated && hasCal ? (r.p90_pax_calibrated ?? 0) : (r.p90_percentage ?? 0)) >= (sq.showCalibrated && hasCal ? 50 : 60)
                                ? 'text-bottleneck'
                                : 'text-text-secondary'
                            }`}
                          >
                            {sq.showCalibrated && hasCal ? (
                              r.p90_pax_calibrated != null ? (
                                <span>{fmtNum1(r.p90_pax_calibrated)} pax</span>
                              ) : (
                                <span className="text-text-muted">—</span>
                              )
                            ) : (
                              fmtPct(r.p90_percentage)
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              );
            })
          ) : (
            <>
              <SourceNote source="occupancy_stats.csv" period="APC load per route-period" className="mx-5" />
              <EmptyState
                title="No crowding snapshots yet"
                hint="The collector is offline or no vehicles have reported occupancy. Crowding appears once occupancy polls land."
              />
            </>
          )}
          {sq.crowd.faulty_vehicles && sq.crowd.faulty_vehicles.length > 0 && (
            <div className="mx-5 mb-4 rounded-lg border border-bottleneck/30 bg-bottleneck/5 px-3 py-2">
              <div className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-bottleneck">
                <AlertTriangle className="h-3 w-3" />
                Faulty APC sensors ({sq.crowd.faulty_vehicles.length} vehicle{sq.crowd.faulty_vehicles.length !== 1 ? 's' : ''})
              </div>
              <div className="mt-1 space-y-0.5 text-[10px] text-text-muted">
                {sq.crowd.faulty_vehicles.map((v) => (
                  <div key={v.vehicle_id}>
                    <span className="font-mono font-semibold text-text-secondary">V{v.vehicle_id}</span>
                    {' '}&mdash; {v.note} ({v.n_observations.toLocaleString()} obs, stuck on MANY_SEATS {v.status1_share}% of the time)
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

  );
}
