import { CalendarRange } from 'lucide-react';

import { Area, AreaChart, CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { SectionHeader } from '../shared';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function TrendsCard({ sq }: { sq: SqCardProps }) {
  return (
    <>
        {sq.trendRows.length > 0 && (
          <section className="overflow-hidden rounded-2xl border border-border bg-card">
            <div id="sq-trends">
            <SectionHeader
              icon={<CalendarRange className="h-4 w-4" />}
              title="Day-over-day trends"
              tone="green"
              freshness={sq.trends?.updated_at ? (
                <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                  Updated {sq.trends!.updated_at}
                </span>
              ) : sq.trendRows.length > 0 ? (
                <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                  {sq.trendRows.length} day{sq.trendRows.length !== 1 ? 's' : ''}
                </span>
              ) : undefined}
            />
            </div>
            <div className="grid grid-cols-1 gap-4 px-5 pb-5 lg:grid-cols-2">
              <div>
                <div className="pb-1 text-[11px] font-bold uppercase tracking-wider text-text-secondary">
                  Ghost trips (per 100 verifiable)
                </div>
                <ResponsiveContainer width="100%" height={160}>
                  <LineChart data={sq.trendData} margin={{ top: 8, right: 8, left: -16, bottom: 0 }}>
                    <CartesianGrid stroke="#2E2E2E" strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
                    <Tooltip contentStyle={{ background: '#1E1E1E', border: '1px solid #2E2E2E', borderRadius: 8, fontSize: 12 }} labelStyle={{ color: '#EDEDED' }} />
                    <Line type="monotone" dataKey="ghost_rate_pct" name="Ghost %" stroke="#FFAB00" strokeWidth={2} dot={{ r: 3 }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
              <div>
                <div className="pb-1 text-[11px] font-bold uppercase tracking-wider text-text-secondary">
                  Early departures (% &gt; 2 min early)
                </div>
                <ResponsiveContainer width="100%" height={160}>
                  <LineChart data={sq.trendData} margin={{ top: 8, right: 8, left: -16, bottom: 0 }}>
                    <CartesianGrid stroke="#2E2E2E" strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis
                      stroke="#9E9E9E"
                      fontSize={11}
                      tickLine={false}
                      axisLine={false}
                      tickFormatter={(v: number) => `${v}%`}
                    />
                    <Tooltip contentStyle={{ background: '#1E1E1E', border: '1px solid #2E2E2E', borderRadius: 8, fontSize: 12 }} labelStyle={{ color: '#EDEDED' }} />
                    <Line type="monotone" dataKey="pct_early_gt2" name="Early %" stroke="#4FC3F7" strokeWidth={2} dot={{ r: 3 }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
              <div className="lg:col-span-2">
                <div className="pb-1 text-[11px] font-bold uppercase tracking-wider text-text-secondary">
                  Recorded departures
                </div>
                <ResponsiveContainer width="100%" height={140}>
                  <AreaChart data={sq.trendData} margin={{ top: 8, right: 8, left: -16, bottom: 0 }}>
                    <defs>
                      <linearGradient id="obsFill" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#00E676" stopOpacity={0.35} />
                        <stop offset="100%" stopColor="#00E676" stopOpacity={0.02} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid stroke="#2E2E2E" strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis
                      stroke="#9E9E9E"
                      fontSize={11}
                      tickLine={false}
                      axisLine={false}
                      tickFormatter={(v: number) =>
                        v >= 1_000_000
                          ? `${(v / 1_000_000).toFixed(v % 1_000_000 === 0 ? 0 : 1)}M`
                          : v.toLocaleString()
                      }
                    />
                    <Tooltip contentStyle={{ background: '#1E1E1E', border: '1px solid #2E2E2E', borderRadius: 8, fontSize: 12 }} labelStyle={{ color: '#EDEDED' }} />
                    <Area type="monotone" dataKey="n_recorded" name="Recorded departures" stroke="#00E676" strokeWidth={2} fill="url(#obsFill)" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
              <span className="text-[10px] text-text-muted">
                {sq.trends?.updated_at ? `Updated ${sq.trends.updated_at}` : 'Rollup history'}. Ghost % = ghosts ÷ verifiable scheduled trips.
              </span>
              <SourceNote source={sq.trends?.file ?? 'weekly_rollup.csv'} />
            </div>
          </section>
        )}
    </>
  );
}