import { Fragment } from 'react';
import { fmtInt, fmtMin, fmtNum1, fmtPct } from '../../../lib/format';
import { TrendingDown, ArrowDownRight } from 'lucide-react';
import { PERIOD_LABELS, StatCard, SectionHeader } from '../shared';
import { EmptyState } from '../../PanelStates';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function LatenessCard({ sq }: { sq: SqCardProps }) {
  return (
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <div id="sq-lateness">
          <SectionHeader
            icon={<TrendingDown className="h-4 w-4" />}
            title="On-time performance (recorded departures)"
            tone="amber"
            freshness={sq.lat.n_observations ? (
              <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                {fmtInt(sq.lat.n_observations)} obs · {sq.lat.routes_covered ?? 0} routes
              </span>
            ) : undefined}
          />
          </div>
          {sq.lat.available ? (
            <>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-2 sm:grid-cols-5">
                <StatCard
                  label="Departures"
                  value={fmtInt(sq.lat.n_observations)}
                  tone="neutral"
                />
                <StatCard
                  label="Mean lateness"
                  value={fmtMin(sq.lat.mean_lateness_min)}
                  sub="negative = early"
                  tone={(sq.lat.mean_lateness_min ?? 0) < 0 ? 'amber' : 'green'}
                />
                <StatCard
                  label="On time (±2 min)"
                  value={fmtPct(sq.lat.pct_on_time)}
                  tone="green"
                />
                <StatCard
                  label="Early (>2 min)"
                  value={fmtPct(sq.lat.pct_early)}
                  sub="the schedule-padding signal"
                  tone="amber"
                />
                <StatCard
                  label="Late (>2 min)"
                  value={fmtPct(sq.lat.pct_late)}
                  tone="neutral"
                />
              </div>
              <div className="px-5 pb-1 text-[10px] text-text-muted">
                On time + early + late = 100% of recorded departures.
              </div>
              <div className="flex items-center gap-1.5 px-5 pb-2 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                <ArrowDownRight className="h-3.5 w-3.5 text-bottleneck" />
                Most early-running routes
              </div>
              <div className="px-5 pb-4">
                <table className="data-table w-full text-left text-xs">
                  <thead>
                    <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
                      <th className="py-1.5 pr-3 font-semibold">Route</th>
                      <th className="py-1.5 pr-3 font-semibold">Mean (min)</th>
                      <th className="py-1.5 pr-3 font-semibold">Early share</th>
                      <th className="py-1.5 text-right font-semibold">Departures</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(sq.lat.top_early_routes ?? []).map((r) => {
                      const isExpanded = sq.expandedRoute === r.route;
                      // Find this route's crowding data across periods
                      const crowdRows = Object.entries(sq.crowd.periods ?? {}).flatMap(
                        ([period, rows]) => rows.filter((cr) => cr.route_short_name === r.route).map((cr) => ({ period, ...cr }))
                      );
                      return (
                        <Fragment key={r.route}>
                          <tr
                            className={`border-b text-text-secondary cursor-pointer transition-colors ${isExpanded ? 'bg-accent/5' : 'border-border/50 hover:bg-card-hover/50'}`}
                            onClick={() => sq.setExpandedRoute(isExpanded ? null : r.route)}
                          >
                            <td className="py-2 pr-3 font-bold text-text-primary">
                              Route {r.route}
                              {isExpanded && <span className="ml-1.5 text-[9px] text-accent">▼</span>}
                            </td>
                            <td className="py-2 pr-3 tabular-nums font-semibold text-bottleneck">
                              {fmtNum1(r.mean_lateness_min)}
                            </td>
                            <td className="py-2 pr-3 tabular-nums">
                              {fmtPct(r.early_share_pct)}
                            </td>
                            <td className="py-2 text-right tabular-nums text-text-muted">
                              {fmtInt(r.n)}
                            </td>
                          </tr>
                          {isExpanded && crowdRows.length > 0 && (
                            <tr key={`${r.route}-detail`}>
                              <td colSpan={4} className="px-3 pb-2">
                                <div className="rounded-lg border border-border bg-bg/60 p-2.5">
                                  <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted mb-1.5">Crowding profile</div>
                                  <div className="flex flex-wrap gap-1.5">
                                    {crowdRows.map((cr) => (
                                      <span key={cr.period} className="inline-flex items-center gap-1 rounded-md border border-border bg-card-hover px-2 py-1 text-[10px]">
                                        <span className="text-text-secondary">{PERIOD_LABELS[cr.period]?.split(' ')[0] ?? cr.period}</span>
                                        <span className={`font-bold ${(cr.crowded_share_pct ?? 0) > 10 ? 'text-bottleneck' : 'text-text-primary'}`}>
                                          {fmtPct(cr.crowded_share_pct)} crowded
                                        </span>
                                        <span className="text-text-muted">· {fmtNum1(cr.mean_percentage)}% load</span>
                                      </span>
                                    ))}
                                  </div>
                                </div>
                              </td>
                            </tr>
                          )}
                        </Fragment>
                      );
                    })}
                  </tbody>
                </table>
              </div>
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  Lateness = departure − schedule; negative means early.
                </span>
                <SourceNote n={sq.lat.n_observations} source={sq.lat.file ?? 'obs_lateness.csv'} />
              </div>
            </>
          ) : (
            <EmptyState
              title="No lateness observations yet"
              hint="The collector is offline or hasn't recorded departures. Start it and this fills in from live GTFS-RT polling."
              command="python scripts/collect_service.py"
            />
          )}
        </section>

  );
}
