import { TrendingDown } from 'lucide-react';
import { fmtInt } from '../../../lib/format';
import { PERIOD_LABELS, PERIOD_ACCENTS, SectionHeader } from '../shared';
import { EmptyState } from '../../PanelStates';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function BoardingsCard({ sq }: { sq: SqCardProps }) {
  return (
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <div id="sq-boardings">
          <SectionHeader
            icon={<TrendingDown className="h-4 w-4" />}
            title="Boardings"
            tone="blue"
            freshness={sq.board.available ? (
              <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                Lower bound from load delta
              </span>
            ) : undefined}
          />
          </div>
          <div className="px-5 pb-3 text-[11px] leading-relaxed text-text-muted">
            Lower bounds from load, not measured counts: a stop where load rose by d points had at
            least d passengers sq.board. These undercount.
          </div>
          <div className="mx-5 mb-3 rounded-lg border border-border bg-card-hover p-2.5">
            <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
              2025 ridership context (MiWay public reports)
            </div>
            <div className="mt-1 flex flex-wrap gap-1.5">
              <span className="rounded-full border border-danger/30 bg-danger/10 px-2 py-0.5 text-[9px] font-semibold text-danger">18 Derry −26%</span>
              <span className="rounded-full border border-danger/30 bg-danger/10 px-2 py-0.5 text-[9px] font-semibold text-danger">5 Dixie −24%</span>
              <span className="rounded-full border border-danger/30 bg-danger/10 px-2 py-0.5 text-[9px] font-semibold text-danger">22 Finch −23%</span>
              <span className="rounded-full border border-optimized/30 bg-optimized/10 px-2 py-0.5 text-[9px] font-semibold text-optimized">74 Explorer +24%</span>
              <span className="rounded-full border border-optimized/30 bg-optimized/10 px-2 py-0.5 text-[9px] font-semibold text-optimized">126 Burnhamthorpe Exp +12%</span>
            </div>
            <div className="mt-1 text-[9px] text-text-muted">
              System ridership fell 10% in 2025 (58.4M → 52.3M boardings). Routes losing riders often correlate with frequency cuts.
            </div>
          </div>
          {sq.board.published_note && (
            <div className="mx-5 mb-3 rounded-lg border border-accent/30 bg-accent/5 px-3 py-2 text-[10px] leading-snug text-text-muted">
              <span className="font-semibold text-accent">Published fallback:</span>{' '}
              {sq.board.published_note}
            </div>
          )}
          {sq.board.available ? (
            Object.entries(sq.board.periods ?? {}).map(([period, rows]) => {
              if (!rows || rows.length === 0) {
                return (
                  <div key={period} className="px-5 pb-4">
                    <div
                      className={`pb-1.5 pt-1 text-[11px] font-bold uppercase tracking-wider ${
                        PERIOD_ACCENTS[period] ?? 'text-text-secondary'
                      }`}
                    >
                      {PERIOD_LABELS[period] ?? period}
                    </div>
                    <div className="text-xs text-text-muted">
                      No usable load profiles yet — collection still warming up this period.
                    </div>
                  </div>
                );
              }
              return (
                <div key={period} className="px-5 pb-4">
                  <div
                    className={`pb-1.5 pt-1 text-[11px] font-bold uppercase tracking-wider ${
                      PERIOD_ACCENTS[period] ?? 'text-text-secondary'
                    }`}
                  >
                    {PERIOD_LABELS[period] ?? period}
                  </div>
                <table className="data-table w-full text-left text-xs">
                  <thead>
                    <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
                      <th className="py-1.5 pr-3 font-semibold">Route</th>
                      <th className="py-1.5 pr-3 font-semibold">Trips</th>
                      <th className="py-1.5 text-right font-semibold">
                        Boardings (lower bound)
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((r) => (
                      <tr
                        key={`b|${period}|${r.route_short_name}`}
                        className="border-b border-border/50 text-text-secondary"
                      >
                        <td className="py-1.5 pr-3 font-bold text-text-primary">
                          Route {r.route_short_name}
                        </td>
                        <td className="py-1.5 pr-3 tabular-nums">{fmtInt(r.n_trips)}</td>
                        <td className="py-1.5 text-right tabular-nums">
                          <span className={`font-bold ${r.source === 'published' ? 'text-text-secondary' : 'text-accent'}`}>
                            {fmtInt(r.boardings_lower_pax)}
                          </span>
                          {r.source === 'published' && (
                            <span className="ml-1 rounded bg-accent/15 px-1 py-0.5 text-[8px] font-semibold uppercase text-accent">
                              est.
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              );
            })
          ) : (
            <>
              <SourceNote source="boardings_routes.csv" period="lower bound from load delta" className="mx-5" />
              <EmptyState
                title="No usable load profiles yet"
                hint="Boarding lower bounds need at least two occupancy polls per trip. Collection may still be warming up."
              />
            </>
          )}
        </section>

  );
}
