import { UserX, AlertTriangle } from 'lucide-react';
import { fmtInt, fmtPct, parseCollectorDate } from '../../../lib/format';
import { StatCard, SectionHeader } from '../shared';
import { EmptyState } from '../../PanelStates';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function GhostTripsCard({ sq }: { sq: SqCardProps }) {
  return (
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <div id="sq-sq.ghosts">
          <SectionHeader
            icon={<UserX className="h-4 w-4" />}
            title="Ghost trips — scheduled buses that never ran"
            tone="amber"
            freshness={sq.ghosts?.available && sq.ghosts.daily && sq.ghosts.daily.length > 0 ? (
              <span className="rounded-full border border-border bg-card-hover px-2 py-0.5 text-[9px] font-semibold text-text-muted">
                {sq.ghosts.daily.length} day{sq.ghosts.daily.length !== 1 ? 's' : ''} · {sq.ghosts.daily[0].date} → {sq.ghosts.daily[sq.ghosts.daily.length - 1].date}
              </span>
            ) : undefined}
          />
          </div>
          {sq.ghosts?.available ? (
            <>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-2 sm:grid-cols-4">
                <StatCard
                  label="Total sq.ghosts"
                  value={fmtInt(sq.ghosts.daily?.reduce((s, d) => s + d.ghosts, 0) ?? sq.ghosts.worst_routes?.reduce((s, r) => s + r.ghosts, 0) ?? 0)}
                  tone="amber"
                />
                <StatCard
                  label="Ghost rate"
                  value={(() => {
                    const totalVerifiable = sq.ghosts.daily?.reduce((s, d) => s + d.verifiable, 0) ?? 0;
                    const totalGhosts = sq.ghosts.daily?.reduce((s, d) => s + d.ghosts, 0) ?? 0;
                    return totalVerifiable > 0 ? `${(totalGhosts / totalVerifiable * 100).toFixed(1)}%` : '—';
                  })()}
                  sub="of verifiable trips"
                  tone="amber"
                />
                <StatCard
                  label="Days collected"
                  value={String(sq.ghosts.daily?.length ?? 0)}
                  sub={sq.ghosts.daily && sq.ghosts.daily.length > 0 ? `${sq.ghosts.daily[0].date} → ${sq.ghosts.daily[sq.ghosts.daily.length - 1].date}` : undefined}
                />
                <StatCard
                  label="Worst day"
                  value={(() => {
                    // Comparable days = well-covered days: the reader no longer
                    // splits detector vintage (every day uses the current
                    // detector), so verifiable share, not date, gates comparability.
                    const fixedDays = (sq.ghosts.daily ?? []).filter((d) => (d.verifiable_share_pct ?? 0) >= 50);
                    const worst = [...fixedDays].sort((a, b) => b.ghost_rate_pct - a.ghost_rate_pct)[0];
                    return worst ? `${worst.ghost_rate_pct}%` : '—';
                  })()}
                  tone="amber"
                />
              </div>
              {sq.ghosts.note && (
                <div className="mx-5 mb-2 flex items-start gap-2 rounded-lg border border-amber-500/30 bg-card px-3 py-2 text-[11px] leading-snug text-text-muted">
                  <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-400" />
                  <span>{sq.ghosts.note}</span>
                </div>
              )}
              {sq.ghosts.rider_impact && sq.ghosts.rider_impact.total_ghosts_with_gap > 0 && (
                <div className="mx-5 mb-3 rounded-xl border border-bottleneck/30 bg-bottleneck/5 p-4">
                  <div className="text-[11px] font-bold uppercase tracking-wider text-bottleneck">
                    Rider impact — extra wait from real ghosts
                  </div>
                  <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-3">
                    <div>
                      <div className="text-2xl font-bold text-text-primary">{Math.round(sq.ghosts.rider_impact.total_extra_wait_minutes).toLocaleString()}</div>
                      <div className="text-[10px] text-text-muted">total extra minutes</div>
                    </div>
                    <div>
                      <div className="text-2xl font-bold text-text-primary">{sq.ghosts.rider_impact.avg_gap_minutes}</div>
                      <div className="text-[10px] text-text-muted">avg min per ghost</div>
                    </div>
                    <div>
                      <div className="text-2xl font-bold text-text-primary">{sq.ghosts.rider_impact.total_ghosts_with_gap}</div>
                      <div className="text-[10px] text-text-muted">ghosts with gap data</div>
                    </div>
                  </div>
                  {sq.ghosts.rider_impact.skipped_phantoms && sq.ghosts.rider_impact.skipped_phantoms > 0 && (
                    <div className="mt-2 text-[10px] text-text-muted">
                      {sq.ghosts.rider_impact.skipped_phantoms} phantom trips excluded (schedule discrepancies)
                    </div>
                  )}
                  {(sq.ghosts.rider_impact.n_holiday_skipped != null || sq.ghosts.rider_impact.n_overnight_stranded != null) && (
                    <div className="mt-2 text-[10px] text-text-muted">
                      {sq.ghosts.rider_impact.n_holiday_skipped != null && sq.ghosts.rider_impact.n_holiday_skipped > 0 && (
                        <span>
                          {sq.ghosts.rider_impact.n_holiday_skipped} holiday ghosts counted but excluded from wait minutes
                        </span>
                      )}
                      {sq.ghosts.rider_impact.n_holiday_skipped != null && sq.ghosts.rider_impact.n_holiday_skipped > 0 && sq.ghosts.rider_impact.n_overnight_stranded != null && sq.ghosts.rider_impact.n_overnight_stranded > 0 && "; "}
                      {sq.ghosts.rider_impact.n_overnight_stranded != null && sq.ghosts.rider_impact.n_overnight_stranded > 0 && (
                        <span>
                          {sq.ghosts.rider_impact.n_overnight_stranded} end-of-night ghosts strand to the next morning's first trip
                        </span>
                      )}
                    </div>
                  )}
                  {sq.ghosts.rider_impact.weighted_extra_wait_minutes != null &&
                    sq.ghosts.rider_impact.weighting_note && (
                      <div className="pb-1 text-[10px] leading-snug text-text-muted">
                        Crush-weighted: {Math.round(sq.ghosts.rider_impact.weighted_extra_wait_minutes).toLocaleString()} min. {sq.ghosts.rider_impact.weighting_note}
                      </div>
                    )}
                  {sq.ghosts.rider_impact.by_route && sq.ghosts.rider_impact.by_route.length > 0 && (
                    <div className="mt-3 space-y-1">
                      {sq.ghosts.rider_impact.by_route.slice(0, 8).map((r) => (
                        <div key={r.route_short_name} className="flex items-center gap-2 text-[11px]">
                          <span className="w-12 font-bold text-text-primary">R{r.route_short_name}</span>
                          <span className="text-bottleneck">+{Math.round(r.extra_wait_minutes)} min</span>
                          {r.standing_share_pct != null && r.standing_share_pct >= 10 && (
                            <span
                              className="rounded bg-bottleneck/15 px-1 py-0.5 text-[9px] font-bold text-bottleneck"
                              title={`${r.standing_share_pct.toFixed(0)}% of polls standing-room-or-worse in the route's worst period`}
                            >
                              {r.standing_share_pct.toFixed(0)}% standing
                            </span>
                          )}
                          <span className="text-text-muted">({r.n_ghosts} sq.ghosts, avg {r.avg_gap_minutes} min)</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
              {sq.ghosts.phantoms && sq.ghosts.phantoms.count > 0 && (
                <div className="mx-5 mb-3 rounded-xl border border-amber-500/30 bg-amber-500/5 p-4">
                  <div className="text-[11px] font-bold uppercase tracking-wider text-amber-400">
                    Schedule discrepancies — {sq.ghosts.phantoms.count} phantom trip{sq.ghosts.phantoms.count !== 1 ? 's' : ''}
                  </div>
                  <div className="mt-1 text-[10px] text-text-muted">
                    {sq.ghosts.phantoms.note ?? 'Trips that ghost on >60% of days — likely deadheads or stale GTFS entries, not real missing buses.'}
                  </div>
                  {sq.ghosts.phantoms.details && sq.ghosts.phantoms.details.length > 0 && (
                    <div className="mt-2 space-y-1">
                      {sq.ghosts.phantoms.details.slice(0, 10).map((p) => (
                        <div key={p.trip_id} className="flex items-center gap-2 text-[10px]">
                          <span className="font-mono text-text-muted">{p.trip_id}</span>
                          <span className="font-bold text-text-secondary">R{p.route}</span>
                          <span className="text-amber-400">{Math.round(p.ghost_rate * 100)}% ghost rate</span>
                          <span className="text-text-muted">({p.ghost_days}/{p.total_days} days)</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
              {sq.ghosts.by_period && sq.ghosts.by_period.length > 0 && (() => {
                const maxGhosts = Math.max(...sq.ghosts.by_period!.map((p: { ghosts: number }) => p.ghosts));
                return (
                  <div className="px-5 pb-4">
                    <div className="pb-1.5 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                      When ghosts happen (time of day)
                    </div>
                    <div className="space-y-1.5">
                      {sq.ghosts.by_period!.map((p) => (
                        <div key={p.period} className="flex items-center gap-2">
                          <span className="w-36 shrink-0 text-[10px] text-text-secondary">{p.period}</span>
                          <div className="flex-1 h-4 overflow-hidden rounded-full bg-border/50">
                            <div
                              className="h-full rounded-full bg-danger/70"
                              style={{ width: `${maxGhosts > 0 ? (p.ghosts / maxGhosts) * 100 : 0}%` }}
                            />
                          </div>
                          <span className="w-10 text-right text-[10px] font-bold tabular-nums text-danger">{p.ghosts}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })()}
              {sq.ghosts.daily && sq.ghosts.daily.length > 2 && (() => {
                const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
                const byDow: Record<string, { ghosts: number; verifiable: number; days: number }> = {};
                for (const d of sq.ghosts.daily!) {
                  if ((d.verifiable_share_pct ?? 0) < 50) continue;
                  // parseCollectorDate normalizes yyyymmdd (20260817) — a raw
                  // one is an Invalid Date and would collapse every day into
                  // one 'undefined' bucket. Unparseable dates land in an
                  // explicit 'unknown' row rather than poisoning a real day.
                  const parsed = parseCollectorDate(d.date);
                  const dow = parsed ? DAY_NAMES[parsed.getDay()] : 'unknown';
                  if (!byDow[dow]) byDow[dow] = { ghosts: 0, verifiable: 0, days: 0 };
                  byDow[dow].ghosts += d.ghosts;
                  byDow[dow].verifiable += d.verifiable;
                  byDow[dow].days += 1;
                }
                const rows = Object.entries(byDow)
                  .map(([day, v]) => ({ day, rate: v.verifiable > 0 ? (v.ghosts / v.verifiable * 100) : 0, ghosts: v.ghosts, days: v.days }))
                  .filter((r) => r.ghosts > 0 || r.days > 0)
                  .sort((a, b) => b.rate - a.rate);
                if (rows.length === 0) return null;
                const maxRate = Math.max(...rows.map((r) => r.rate));
                return (
                  <div className="px-5 pb-4">
                    <div className="pb-1.5 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                      Ghosts by day of week
                    </div>
                    <div className="space-y-1.5">
                      {rows.map((r) => (
                        <div key={r.day} className="flex items-center gap-2">
                          <span className="w-10 shrink-0 text-[10px] font-semibold text-text-secondary">{r.day}</span>
                          <div className="flex-1 h-4 overflow-hidden rounded-full bg-border/50">
                            <div
                              className="h-full rounded-full bg-bottleneck/70"
                              style={{ width: `${maxRate > 0 ? (r.rate / maxRate) * 100 : 0}%` }}
                            />
                          </div>
                          <span className="w-16 text-right text-[10px] tabular-nums text-text-secondary">
                            <span className="font-bold text-bottleneck">{r.rate.toFixed(1)}%</span>
                            <span className="text-text-muted"> ({r.ghosts})</span>
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })()}
              {sq.ghosts.blocks && sq.ghosts.blocks.length > 0 && (
                <div className="px-5 pb-4">
                  <div className="pb-1.5 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                    Missing vehicles (ghosts grouped by bus)
                  </div>
                  <div className="space-y-1">
                    {sq.ghosts.blocks.map((b) => (
                      <div
                        key={`${b.date}|${b.block}`}
                        className="flex items-center gap-2 rounded-lg border border-border/60 bg-card px-2.5 py-1.5 text-[11px]"
                      >
                        <span className="w-11 shrink-0 font-bold text-text-primary">
                          R{b.route_short_name}
                        </span>
                        <span className="font-mono text-[10px] text-text-muted">
                          {b.block}
                        </span>
                        <span
                          className={
                            b.likely_missing_vehicle
                              ? 'font-bold text-danger'
                              : 'text-text-secondary'
                          }
                        >
                          {b.n_ghosts} trips
                        </span>
                        <span className="text-text-muted">{b.date}</span>
                        <span className="ml-auto tabular-nums text-text-secondary">
                          {sq.fmtHM(b.span_from_min)}–{sq.fmtHM(b.span_to_min)}
                        </span>
                        {b.likely_missing_vehicle && (
                          <span
                            className={
                              b.singleton_rule === 'crowded_route'
                                ? 'rounded bg-bottleneck/15 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-bottleneck'
                                : 'rounded bg-danger/15 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-danger'
                            }
                            title={
                              b.singleton_rule === 'crowded_route'
                                ? 'Lone ghost on a crush-prone route — the next bus inherits the full load'
                                : b.singleton_rule === 'low_frequency'
                                  ? 'Lone ghost on a low-frequency route — the next bus is 30+ min away'
                                  : 'Whole vehicle absent'
                            }
                          >
                            {b.singleton_rule === 'crowded_route'
                              ? 'crush load'
                              : b.singleton_rule === 'low_frequency'
                                ? 'long wait'
                                : 'missing bus'}
                          </span>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {sq.ghosts.daily && sq.ghosts.daily.length > 0 && (
                <div className="px-5 pb-4">
                  <div className="pb-1.5 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                    Daily breakdown (missing buses = vehicles absent: 4+ trips, or 1 trip on a slow/crowded route)
                  </div>
                  <table className="data-table w-full text-left text-xs">
                    <thead>
                      <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
                        <th className="py-1.5 pr-3 font-semibold">Date</th>
                        <th className="py-1.5 pr-3 font-semibold">Ghosts</th>
                        <th className="py-1.5 pr-3 font-semibold">Rate</th>
                        <th className="py-1.5 pr-3 font-semibold">Verifiable</th>
                        <th className="py-1.5 text-right font-semibold">Missing buses</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sq.ghosts.daily.map((d) => (
                        <tr
                          key={d.date}
                          className="border-b border-border/50 text-text-secondary"
                        >
                          <td className="py-1.5 pr-3 font-bold text-text-primary">{d.date}</td>
                          <td className="py-1.5 pr-3 tabular-nums">{fmtInt(d.ghosts)}</td>
                          <td className="py-1.5 pr-3 tabular-nums">{fmtPct(d.ghost_rate_pct)}</td>
                          <td className="py-1.5 pr-3 tabular-nums">{fmtInt(d.verifiable)}</td>
                          <td
                            className={`py-1.5 text-right tabular-nums font-bold ${
                              (d.missing_vehicles ?? 0) > 0 ? 'text-danger' : 'text-text-muted'
                            }`}
                          >
                            {d.missing_vehicles ?? 0}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
              {sq.ghosts.worst_routes && sq.ghosts.worst_routes.length > 0 && (
                <div className="px-5 pb-4">
                  <div className="pb-1.5 text-[11px] font-bold uppercase tracking-wider text-text-muted">
                    Routes with the most ghosts
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {sq.ghosts.worst_routes.map((r) => (
                      <span
                        key={r.route_short_name}
                        className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card-hover px-2 py-1 text-[11px]"
                      >
                        <span className="font-bold text-text-primary">Route {r.route_short_name}</span>
                        <span className="font-semibold text-danger">{r.ghosts} ghost{r.ghosts !== 1 ? 's' : ''}</span>
                        <span className="text-text-muted">/ {fmtInt(r.verifiable)} trips</span>
                      </span>
                    ))}
                  </div>
                </div>
              )}
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  A ghost is a trip the schedule says should run whose bus never appeared in the live feed.
                </span>
                <SourceNote source={sq.ghosts.file ?? 'ghost_trips.csv'} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No ghost-trip data yet"
                hint="The collector may be offline, or the ghost-trip analysis hasn't been regenerated."
                command="python scripts/ghost_trips.py"
              />
            </div>
          )}
        </section>

  );
}
