import { useState, useEffect } from 'react';
import { Activity, ShieldCheck } from 'lucide-react';
import { api } from '../lib/api';
import type { OperationsTrends, ServiceQualityResponse, WeeklyRollupRow } from '../types';
import { PanelSkeleton } from './PanelStates';
import NewHereHint from './NewHereHint';
import { LatenessCard } from './sq/cards/LatenessCard';
import { CrowdingCard } from './sq/cards/CrowdingCard';
import { CalibrationCard } from './sq/cards/CalibrationCard';
import { BoardingsCard } from './sq/cards/BoardingsCard';
import { GhostTripsCard } from './sq/cards/GhostTripsCard';
import { TrendsCard } from './sq/cards/TrendsCard';



/**
 * Service Quality shell (T158 fold rule 4). Formerly a 1,202-line monolith;
 * now the Measure shell's "Service quality" section — owns data loading and
 * state, renders the six sub-cards in `sq/cards/`, whose markup moved out
 * VERBATIM during the split. Section-anchored jump-links (sq-ghosts,
 * sq-trends) still resolve inside the composed card stack.
 */

export default function ServiceQualityPanel() {
  const [data, setData] = useState<ServiceQualityResponse | null>(null);
  const [trends, setTrends] = useState<OperationsTrends | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [expandedRoute, setExpandedRoute] = useState<string | null>(null);
  const [showCalibrated, setShowCalibrated] = useState(false);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const [sq, t] = await Promise.all([api.serviceQuality(), api.operationsTrends()]);
      setData(sq);
      setTrends(t);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  if (loading && !data) return <PanelSkeleton label="Loading service quality…" />;

  if (error) {
    return (
      <div role="alert" className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger">
        Could not load service quality: {error}
      </div>
    );
  }
  if (!data) return null;

  const lat = data.lateness;
  const crowd = data.crowding;
  const board = data.boardings;
  const ghosts = data.ghost_trips;
  const groundTruth = data.ground_truth;
  const subValidated = (groundTruth?.routes ?? []).filter(
    (r) => r.trust !== 'validated' && r.trust !== 'biased'
  );
  const trendRows = trends?.rows ?? [];
  const trendData = trendRows.map((r: WeeklyRollupRow) => ({ ...r, date: r.date.slice(5) }));

  // minute-of-day (e.g. 662) -> "11:02" clock time.
  const fmtHM = (m: number) =>
    `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(Math.round(m % 60)).padStart(2, '0')}`;

  const sq = { lat, crowd, board, ghosts, groundTruth, subValidated, trends, trendRows, trendData,
               expandedRoute, setExpandedRoute, showCalibrated, setShowCalibrated, fmtHM };

  return (
    <div className="flex flex-col">
      {/* header — verbatim from the pre-split panel */}
      <div className="relative overflow-hidden rounded-2xl border border-border bg-card px-5 py-5">
        <div className="absolute inset-x-0 top-0 h-1 edge-gradient-green" />
        <div className="flex items-center gap-2.5">
          <span className="rounded-xl bg-optimized/15 p-2">
            <Activity className="h-5 w-5 text-optimized" />
          </span>
          <h2 className="text-base font-bold text-text-primary">Service quality</h2>
          <span className="inline-flex items-center gap-1 rounded-full border border-optimized/30 bg-optimized/10 px-2 py-0.5 text-[10px] font-semibold text-optimized">
            <ShieldCheck className="h-3 w-3" /> measured
            <span className="live-dot ml-0.5 h-1.5 w-1.5 rounded-full bg-optimized" />
          </span>
        </div>
        <p className="mt-2 text-xs leading-relaxed text-text-muted">
          What the collector has actually observed on the street — real GTFS-RT lateness and APC
          load. Read-only: nothing here is modeled.
        </p>
      </div>
      <div className="mt-3">
        <NewHereHint text="This page is the measured half of the project: real vehicle observations of how early buses run, which routes fill up, and a lower bound on boardings. The other half — what we'd change — lives in the planning views." />
      </div>

      {/* jump-links */}
      <div className="mt-3 flex flex-wrap items-center gap-1.5">
        <span className="text-[10px] font-semibold uppercase tracking-wider text-text-muted">Jump to:</span>
        {[
          { id: 'sq-lateness', label: 'Lateness' },
          { id: 'sq-crowding', label: 'Crowding' },
          { id: 'sq-boardings', label: 'Boardings' },
          ghosts?.available ? { id: 'sq-ghosts', label: 'Ghost trips' } : null,
          trendRows.length > 0 ? { id: 'sq-trends', label: 'Trends' } : null,
        ].filter(Boolean).map((item) => (
          <a
            key={item!.id}
            href={`#${item!.id}`}
            onClick={(e) => {
              e.preventDefault();
              document.getElementById(item!.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }}
            className="rounded-md border border-border bg-card-hover px-2 py-1 text-[10px] font-semibold text-text-secondary transition-colors hover:border-optimized/50 hover:text-optimized"
          >
            {item!.label}
          </a>
        ))}
      </div>

      <div className="mt-4 flex flex-col gap-4">
        <LatenessCard sq={sq} />
        <CrowdingCard sq={sq} />
        <CalibrationCard sq={sq} />
        <BoardingsCard sq={sq} />
        <GhostTripsCard sq={sq} />
        <TrendsCard sq={sq} />
      </div>
    </div>
  );
}
