import { Crosshair } from 'lucide-react';
import { fmtInt, fmtNum1, fmtPct } from '../../../lib/format';
import { TrustBadge, SectionHeader } from '../shared';
import { EmptyState } from '../../PanelStates';
import SourceNote from '../../SourceNote';
import type { SqCardProps } from '../types';


export function CalibrationCard({ sq }: { sq: SqCardProps }) {
  return (
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <SectionHeader
            icon={<Crosshair className="h-4 w-4" />}
            title="Ground-truth calibration (ride-alongs)"
            tone="amber"
          />
          {sq.groundTruth && sq.groundTruth.available && sq.groundTruth.routes.length > 0 ? (
            <>
              <div className="px-5 pb-3 text-[11px] leading-relaxed text-text-muted">
                Observer-counted loads vs. the sensor: the sensor quantizes to multiples of
                20% with a wide floor, so{' '}
                <b>
                  {fmtPct(sq.groundTruth.floor_share_pct)} of the {fmtInt(sq.groundTruth.n_checkins)}{' '}
                  check-ins sat at exactly 20%
                </b>{' '}
                — the "Mean load %" above includes that floor. Bias = counted − sensor pax:
                positive means the sensor-derived pax undercounts real riders.
              </div>
              <div className="flex flex-wrap items-center gap-1.5 px-5 pb-3 text-[10px] text-text-muted">
                <span className="font-bold uppercase tracking-wider">Sensor readings:</span>
                {(sq.groundTruth.pct_buckets ?? {}) &&
                  Object.entries(sq.groundTruth.pct_buckets ?? {}).map(([pct, n]) => (
                    <span
                      key={pct}
                      className="rounded-md border border-border bg-card-hover px-1.5 py-0.5 tabular-nums"
                    >
                      {pct}% × {fmtInt(n)}
                    </span>
                  ))}
              </div>
              <div className="px-5 pb-4">
                <table className="data-table w-full text-left text-xs">
                  <thead>
                    <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
                      <th className="py-1.5 pr-3 font-semibold">Route</th>
                      <th className="py-1.5 pr-3 font-semibold">Check-ins</th>
                      <th className="py-1.5 pr-3 font-semibold">Counted</th>
                      <th className="py-1.5 pr-3 font-semibold">Sensor pax</th>
                      <th className="py-1.5 pr-3 font-semibold">Bias</th>
                      <th className="py-1.5 pr-3 font-semibold">MAE</th>
                      <th className="py-1.5 text-right font-semibold">Trust</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sq.groundTruth.routes
                      .filter((r) => r.trust === 'validated' || r.trust === 'biased')
                      .map((r) => (
                      <tr
                        key={r.route}
                        className="border-b border-border/50 text-text-secondary"
                      >
                        <td className="py-2 pr-3 font-bold text-text-primary">Route {r.route}</td>
                        <td className="py-2 pr-3 tabular-nums">{fmtInt(r.checkins)}</td>
                        <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.mean_counted_pax)}</td>
                        <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.mean_sensor_pax)}</td>
                        <td
                          className={`py-2 pr-3 tabular-nums font-bold ${
                            (r.bias_pax ?? 0) > 2
                              ? 'text-bottleneck'
                              : (r.bias_pax ?? 0) < -2
                                ? 'text-accent'
                                : 'text-text-secondary'
                          }`}
                        >
                          {r.bias_pax != null
                            ? `${r.bias_pax > 0 ? '+' : ''}${fmtNum1(r.bias_pax)}`
                            : '—'}
                        </td>
                        <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.mae_pax)}</td>
                        <td className="py-2 text-right">
                          <TrustBadge trust={r.trust} />
                        </td>
                      </tr>
                      ))}
                    {sq.subValidated.length > 0 && (
                      <tr className="border-b border-border/50 bg-card-hover/40">
                        <td className="py-2 pr-3 font-semibold text-text-muted" colSpan={7}>
                          + {sq.subValidated.length} route{sq.subValidated.length > 1 ? 's' : ''} held out
                          ({sq.subValidated.map((r) => r.route).join(', ')}): bias shown only once a
                          route reaches n≥20 — ride these to promote them.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  Sensor pax = the 65-pax conversion; route 42's −10-ish bias is the articulated
                  bus (real capacity ~110). Trust: validated (n≥20, |bias|≤3) · biased (n≥20) ·
                  directional (n≥10) · insufficient.
                </span>
                <SourceNote source={sq.groundTruth.file ?? 'ground_truth.csv'} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No ground-truth rides yet"
                hint="Ride-alongs (observer counts vs. sensor) calibrate the occupancy numbers above. Add them to ground_truth.csv and this fills in per route."
              />
            </div>
          )}
        </section>

  );
}
